-- Generated from supabase/seed/warning_lights.json. Re-run to refresh the catalog.
on conflict (slug) do update set name = excluded.name, colors = excluded.colors, severity = excluded.severity,
  symbol_hint = excluded.symbol_hint, meaning = excluded.meaning, action = excluded.action,
  drive_advice = excluded.drive_advice, brand_notes = excluded.brand_notes,
  brand_severity = excluded.brand_severity, sort_order = excluded.sort_order;
