insert into public.warning_lights (slug, name, colors, severity, symbol_hint, meaning, action, drive_advice, brand_notes, brand_severity, sort_order) values
('check-engine', 'Check engine light', array['amber']::text[], 'soon', 'Outline of an engine block seen from the side, sometimes with the word CHECK.', 'The engine computer found a problem with the engine, fuel or emissions system. Causes range from a loose gas cap to a misfire.', 'If it''s steady, tighten the gas cap and get the code read soon (many auto parts stores do it free). If it''s flashing, the engine is misfiring: slow down and get to a mechanic right away.', 'Steady: OK to drive short-term. Flashing: avoid driving.', '{"tesla": "Teslas have no gasoline engine, so this symbol won''t appear; check the touchscreen alerts instead."}'::jsonb, '{}'::jsonb, 1),
('oil-pressure', 'Oil pressure warning', array['red']::text[], 'stop', 'Old-fashioned oil can with a drip coming from the spout.', 'The engine isn''t getting enough oil pressure. Driving like this can destroy the engine within minutes.', 'Pull over safely and turn the engine off. Once it has rested, check the oil level and add oil if it''s low. If the level is fine or the light stays on, have the car towed.', 'Do not drive.', '{}'::jsonb, '{}'::jsonb, 2),
('oil-level-low', 'Low engine oil level', array['amber']::text[], 'soon', 'Oil can with a wavy line underneath, or oil can with MIN.', 'The oil level sensor reads low oil. This is a level warning, not a pressure warning.', 'Check the dipstick and top up with the oil type in your owner''s manual. Look for leaks if it keeps dropping.', 'OK to drive to a store or service station.', '{"bmw": "BMWs often have no dipstick; check the level in iDrive under Vehicle Status.", "mercedes-benz": "Check the level in the instrument cluster menu."}'::jsonb, '{}'::jsonb, 3),
('coolant-temp', 'Engine temperature warning', array['red']::text[], 'stop', 'Thermometer standing in wavy lines of liquid.', 'The engine is overheating.', 'Pull over and turn the engine off. Never open the radiator cap while hot. Once cool, check the coolant level and have the cooling system inspected.', 'Do not drive until it has cooled and been checked.', '{}'::jsonb, '{}'::jsonb, 4),
('coolant-cold', 'Engine cold indicator', array['blue']::text[], 'info', 'Blue thermometer in wavy lines of liquid.', 'The engine hasn''t reached normal operating temperature yet.', 'Nothing to fix. Drive gently until it goes out.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 5),
('battery-charging', 'Battery / charging warning', array['red']::text[], 'soon', 'Rectangle shaped like a car battery with + and - marks.', 'The charging system isn''t working, so the car is running on battery power alone.', 'Turn off non-essential electronics such as the radio and seat heaters, and drive straight to a mechanic. The car may stall once the battery drains.', 'Drive only a short distance, directly to help.', '{}'::jsonb, '{}'::jsonb, 6),
('brake-system', 'Brake system warning', array['red']::text[], 'stop', 'Circle with an exclamation mark inside, between two curved brackets, or the word BRAKE.', 'Either the parking brake is on, or the brake system has a problem such as low brake fluid.', 'Make sure the parking brake is fully released. If it stays on, check the brake fluid level. If the pedal feels soft or different, stop and have the car towed.', 'Do not drive if braking feels different.', '{}'::jsonb, '{}'::jsonb, 7),
('parking-brake', 'Parking brake on', array['red','amber']::text[], 'info', 'Circle with the letter P inside, between two curved brackets.', 'The parking brake (electronic or manual) is applied.', 'Release the parking brake before driving. If it won''t release or the light is amber and flashing, the electronic parking brake has a fault.', 'Release before driving.', '{}'::jsonb, '{}'::jsonb, 8),
('abs', 'ABS warning', array['amber']::text[], 'soon', 'The letters ABS inside a circle between two curved brackets.', 'The anti-lock braking system is off. Normal brakes still work, but the wheels can lock in a hard stop.', 'Drive carefully with extra following distance, especially in rain or snow, and have it checked soon.', 'OK to drive carefully.', '{}'::jsonb, '{}'::jsonb, 9),
('brake-pad-wear', 'Brake pad wear', array['amber']::text[], 'soon', 'Circle between curved brackets with dashed lines on each side.', 'The brake pads are worn down to their wear sensors.', 'Book a brake service soon. Waiting too long can damage the rotors.', 'OK to drive; schedule service.', '{}'::jsonb, '{}'::jsonb, 10),
('tpms', 'Low tire pressure (TPMS)', array['amber']::text[], 'soon', 'Horseshoe-shaped tire cross-section with an exclamation mark inside.', 'One or more tires is significantly underinflated.', 'Check all four tires with a gauge and fill to the pressure on the driver''s door sticker. If it flashes for a minute then stays on, a sensor needs service.', 'Drive slowly to the nearest air pump.', '{}'::jsonb, '{}'::jsonb, 11),
('traction-control', 'Traction / stability control', array['amber']::text[], 'info', 'Car with two wavy skid lines behind it.', 'Flashing means the system is actively helping you keep grip. Steady means it''s off or has a fault.', 'If flashing, ease off the accelerator. The road is slippery. If steady, check whether it was switched off by a button, and have it inspected if it stays on.', 'OK to drive carefully.', '{"chevrolet": "Chevrolet calls this StabiliTrak; a ''Service StabiliTrak'' message means a fault.", "gmc": "GMC calls this StabiliTrak.", "nissan": "Nissan also shows a SLIP indicator when the system is working."}'::jsonb, '{}'::jsonb, 12),
('traction-off', 'Traction / stability control off', array['amber']::text[], 'info', 'Car with skid lines and the word OFF.', 'Traction or stability control has been turned off.', 'Press the traction-control button to turn it back on unless you''re stuck in snow or mud.', 'OK to drive; turn back on for normal driving.', '{}'::jsonb, '{}'::jsonb, 13),
('airbag', 'Airbag warning', array['red','amber']::text[], 'soon', 'Seated person with a seatbelt and a large circle (airbag) in front.', 'The airbag system has a fault, so airbags may not deploy in a crash.', 'Make sure nothing is blocking or unplugged under the front seats, then have the system checked soon. This is a safety issue.', 'OK to drive, but get it fixed soon.', '{}'::jsonb, '{}'::jsonb, 14),
('seatbelt', 'Seatbelt reminder', array['red']::text[], 'info', 'Seated person wearing a diagonal seatbelt.', 'Someone in a front seat isn''t buckled.', 'Buckle up. A heavy bag on the passenger seat can also trigger it.', 'Buckle up first.', '{}'::jsonb, '{}'::jsonb, 15),
('power-steering', 'Power steering warning', array['red','amber']::text[], 'soon', 'Steering wheel with an exclamation mark beside it.', 'The power steering system has a fault, so steering may become very heavy.', 'Drive slowly to a safe place. Restarting the car sometimes clears it; if not, have it checked.', 'Drive with caution only if steering still feels normal.', '{}'::jsonb, '{}'::jsonb, 16),
('transmission-temp', 'Transmission temperature', array['red','amber']::text[], 'stop', 'Gear cog with a thermometer inside.', 'The transmission fluid is overheating, often from towing or stop-and-go traffic in heat.', 'Pull over, put it in Park, and let the engine idle a few minutes to cool. Have the transmission fluid checked.', 'Stop and let it cool before continuing.', '{}'::jsonb, '{}'::jsonb, 17),
('master-warning', 'Master warning', array['red','amber']::text[], 'soon', 'Triangle with an exclamation mark inside.', 'A general alert that comes on together with a message on the instrument display.', 'Read the message on the dashboard display. That message tells you the actual problem.', 'Depends on the message shown.', '{"toyota": "Toyota and Lexus use this as the Master Warning; it always pairs with a message in the multi-information display.", "lexus": "Pairs with a message in the multi-information display.", "honda": "Check the driver information interface for the specific message."}'::jsonb, '{}'::jsonb, 18),
('service-wrench', 'Service / maintenance indicator', array['amber']::text[], 'info', 'A wrench (spanner), sometimes with letters or a number next to it.', 'A scheduled service is due.', 'Book routine maintenance. Most cars let you reset this after service.', 'OK to drive.', '{"honda": "This is Honda''s Maintenance Minder. The code next to the wrench (like A1 or B12) says which services are due: A = oil change, B = oil + inspection, 1 = tire rotation.", "acura": "This is Acura''s Maintenance Minder; the code shows which services are due.", "ford": "On Fords an amber wrench means a powertrain fault, not routine service. Have it checked soon; the car may limit power.", "lincoln": "An amber wrench indicates a powertrain fault; have it checked soon."}'::jsonb, '{"ford": "soon", "lincoln": "soon"}'::jsonb, 19),
('low-fuel', 'Low fuel', array['amber']::text[], 'info', 'Gas pump.', 'The fuel tank is nearly empty, usually about 30 to 50 miles left.', 'Fill up soon. Running out can damage the fuel pump.', 'Head to a gas station.', '{}'::jsonb, '{}'::jsonb, 20),
('washer-fluid', 'Low washer fluid', array['amber']::text[], 'info', 'Windshield with a fountain of spray.', 'The windshield washer fluid reservoir is low.', 'Top up with washer fluid. Use a de-icer formula in winter.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 21),
('door-ajar', 'Door open', array['red']::text[], 'info', 'Car seen from above with a door swung open.', 'A door, the hood or the trunk isn''t fully closed.', 'Close every door, the hood and the trunk firmly.', 'Close it before driving.', '{}'::jsonb, '{}'::jsonb, 22),
('bulb-out', 'Exterior bulb failure', array['amber']::text[], 'info', 'Light bulb with an exclamation mark or rays.', 'A headlight, brake light or turn signal bulb has burned out.', 'Walk around the car with the lights on to find it, then replace the bulb.', 'OK to drive; fix soon (it''s a ticketable offense).', '{}'::jsonb, '{}'::jsonb, 23),
('glow-plug', 'Glow plug (diesel)', array['amber']::text[], 'info', 'Coil or spiral shape.', 'On diesel engines, the glow plugs are warming the cylinders before starting.', 'Wait for it to go out before starting the engine. If it flashes while driving, there''s an engine fault.', 'Wait for it to go out.', '{}'::jsonb, '{}'::jsonb, 24),
('dpf', 'Diesel particulate filter', array['amber']::text[], 'soon', 'Box with dots inside, like a filter, sometimes with lines on each side.', 'The diesel particulate filter is clogging up.', 'Drive at highway speed for 15 to 20 minutes so it can clean itself. If the light stays on, see a mechanic.', 'OK to drive; a highway drive often clears it.', '{}'::jsonb, '{}'::jsonb, 25),
('def-low', 'Low diesel exhaust fluid (DEF / AdBlue)', array['amber']::text[], 'soon', 'Droplet or fluid container, often with DEF or AdBlue text.', 'The diesel exhaust fluid tank is low. When it runs out, many trucks limit speed or won''t restart.', 'Refill DEF at a gas station or auto parts store.', 'Refill soon.', '{}'::jsonb, '{}'::jsonb, 26),
('epc', 'EPC (Electronic Power Control)', array['amber']::text[], 'soon', 'The letters EPC.', 'A fault in the throttle or engine management system. The car may go into reduced-power ''limp'' mode.', 'Have the fault codes read soon.', 'Drive gently to a mechanic.', '{"volkswagen": "EPC is a Volkswagen/Audi light, often caused by a throttle body or brake light switch fault.", "audi": "EPC often points to the throttle body or brake light switch."}'::jsonb, '{}'::jsonb, 27),
('lane-assist', 'Lane keeping assist', array['green','amber']::text[], 'info', 'Car between two lane lines, sometimes with a steering wheel.', 'Green means lane keeping is active. Amber means it''s unavailable or has a fault, often because the camera is blocked by dirt, snow or glare.', 'If amber, clean the windshield in front of the camera. If it stays amber, have it checked.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 28),
('collision-system', 'Collision avoidance / driver assist off', array['amber']::text[], 'info', 'Car with crash marks or wavy radar lines in front, often with OFF.', 'Forward collision warning or automatic emergency braking is turned off or unavailable.', 'Clean the front sensors and windshield camera. Check the settings menu in case it was switched off.', 'OK to drive with extra attention.', '{"subaru": "On Subarus this appears as ''EyeSight OFF'' or ''EyeSight Disabled'', often from a dirty windshield, glare or heavy rain.", "toyota": "Toyota calls this the Pre-Collision System (PCS).", "honda": "Honda calls this the Collision Mitigation Braking System (CMBS)."}'::jsonb, '{}'::jsonb, 29),
('cruise-control', 'Cruise control', array['green','white']::text[], 'info', 'Speedometer dial with an arrow pointing at it.', 'Cruise control is on or set.', 'Nothing to fix.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 30),
('high-beam', 'High beams on', array['blue']::text[], 'info', 'D-shaped headlight with straight horizontal lines.', 'The high-beam headlights are on.', 'Switch to low beams for oncoming traffic.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 31),
('headlights', 'Headlights on', array['green']::text[], 'info', 'Two small lamps facing outward with short rays, or a D-shaped lamp with angled lines.', 'The headlights or parking lights are on.', 'Nothing to fix.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 32),
('fog-lights', 'Fog lights on', array['green','amber']::text[], 'info', 'Lamp with angled lines crossed by a wavy line.', 'Front fog lights (green) or rear fog light (amber) are on.', 'Turn rear fog lights off in clear weather. They dazzle drivers behind you.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 33),
('auto-stop-start', 'Auto stop-start', array['green','amber']::text[], 'info', 'Letter A inside a circular arrow.', 'Green: the engine has shut off at a stop to save fuel. Amber or with OFF: the system is off or unavailable.', 'Nothing to fix. The engine restarts when you lift off the brake.', 'OK to drive.', '{"mazda": "Mazda calls this i-stop."}'::jsonb, '{}'::jsonb, 34),
('key-not-detected', 'Key fob not detected / low key battery', array['red','amber']::text[], 'info', 'Key shape, sometimes with an exclamation mark or inside a car outline.', 'The car can''t detect the key fob, often because its battery is low.', 'Hold the fob against the start button to start, and replace the fob battery soon.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 35),
('hybrid-system', 'Hybrid / EV system warning', array['red','amber']::text[], 'soon', 'Car outline with an exclamation mark, or a battery with a plug.', 'The hybrid or electric drive system has a fault.', 'Pull over when safe, restart the car, and if it stays on, contact a dealer. Don''t try to service high-voltage parts yourself.', 'Drive only if the car still drives normally, directly to service.', '{"toyota": "Toyota hybrids show ''Check Hybrid System''.", "tesla": "Tesla shows these alerts on the touchscreen; check the alert code there."}'::jsonb, '{}'::jsonb, 36),
('ready', 'Ready to drive (hybrid / EV)', array['green']::text[], 'info', 'The word READY or a car with arrows.', 'A hybrid or electric car is on and ready to move, even though it''s silent.', 'Nothing to fix.', 'OK to drive.', '{}'::jsonb, '{}'::jsonb, 37)
